  veredicto: "El Wolf Warrior 11 es el Kaabo que popularizó el hiperpatinete de doble vástago: chasis forjado, controladoras Minimotors y la opción de empujar solo atrás o con los dos motores a la vez. Sus 90 km declarados se quedan en unos 60 km reales según esta ficha, y su terreno natural es la pista privada y el camino de tierra, no la ciudad: pesa 45 kg, se recarga en unas 13 horas y no encaja en la figura del VMP español. Como compra de ocasión para terreno privado sigue teniendo sentido; si quieres estrenar un Kaabo de esta familia, compáralo antes con el Wolf King GT Pro.",
