  pros: ["Su batería de 36 V y 10 Ah (360 Wh) se desmonta del mástil sin herramientas y se carga en cualquier enchufe interior, sin tener que subir los 15 kg del patinete a casa", "Declara 48 km y esta ficha le atribuye 32 km reales con un motor de solo 350 W, margen de sobra para una ida y vuelta al trabajo sin cargar a mitad de jornada", "Las ruedas neumáticas de 10 pulgadas con cámara, frente a las de 8,5 del X7 original, son su única amortiguación y filtran adoquines y juntas mejor que las de su antecesor", "Admite hasta 125 kg de carga, 25 kg más que el Xiaomi Mi Scooter Pro 2 con el que Gizmodo lo comparó en 2020, pese a quedarse en 15 kg de peso propio"],
  contras: ["Recuperar los 360 Wh desde cero lleva 6 horas, así que enlazar dos jornadas largas sin esperas pasa casi obligatoriamente por comprar una segunda batería de repuesto", "La batería que lo hace práctico no lleva cerradura en el X7 Pro: Gizmodo advirtió de que cualquiera puede extraerla si lo dejas aparcado en la calle, un fallo que TurboAnt corrigió después añadiendo bloqueo en el X7 Max", "Al llevar la batería en el mástil queda delantero-pesado y con el centro de gravedad alto: al levantarlo desplegado la rueda trasera bascula y al subir bordillos cuesta más que en un patinete con la batería en la plataforma", "Con 350 W nominales y una pendiente máxima declarada de 15°, un conductor cercano a los 125 kg de carga máxima notará que en cuestas pronunciadas pierde empuje y velocidad"],
