  aprox: ["precioEur", "autonomiaRealKm", "velocidadMaxKmh"],
  pros: ["Su motor de 500 W mueve sin ahogarse a un conductor de hasta 120 kg de carga máxima declarada: en las rampas cortas de un recorrido urbano no tienes que ayudarle con el pie como sí ocurre en los urbanos de 250-300 W", "Los 374 Wh —36 V y 10,4 Ah— se traducen en unos 27 km reales por carga frente a los 40 km anunciados: suficiente para encadenar dos o tres jornadas cortas de casa al trabajo antes de enchufarlo", "Trae de serie dos cierres que sus rivales de precio venden por separado: un código electrónico de 3 dígitos en la consola, que pita y bloquea si intentan encenderlo, y un candado de cable de 4 dígitos integrado en el mástil", "Las ruedas neumáticas de 10 pulgadas, precargadas con líquido antipinchazos según las pruebas del modelo, son su única amortiguación y aun así ruedan con más aplomo sobre adoquín y juntas de dilatación que las de 8,5 pulgadas habituales en esta franja"],
  contras: ["Sale de fábrica con 20 mph —32 km/h— en su segundo modo, por encima del tope de 25 km/h de un VMP en España, y la ficha no ha podido verificar su certificado DGT en la lista oficial: tal cual llega, no lo des por legal aquí", "Los 449 € de la ficha figuran como aproximados y sin precio verificado en España: Gotrax no tiene distribución ni servicio técnico oficial en este país, así que una avería de motor o batería se resuelve por correo con el vendedor, no en un taller cercano", "No monta suspensión delante ni detrás: todo lo que no filtre la rueda de 10 pulgadas llega directo a tus muñecas, y en calles con baches seguidos toca bajar el ritmo o acabar con los brazos cargados", "Recargar los 374 Wh lleva unas 6 horas con su cargador: si la jornada te deja la batería seca a media tarde, no hay una carga breve que te rescate el trayecto de vuelta"],
  veredicto: "Por unos 449 € aproximados, el G4 junta un motor de 500 W, una batería de 374 Wh con unos 27 km aprovechables —no los 40 km del folleto— y 17 kg de peso, un equilibrio pensado para ir y volver a diario sin recargar a mediodía. Encaja si tus trayectos son urbanos, mayoritariamente llanos y valoras dejarlo atado con su doble bloqueo sin comprar un candado aparte. No encaja si lo necesitas ya como VMP legal en España —de fábrica marca 32 km/h y no consta su certificado DGT— ni si quieres un taller de la marca al que acudir en España cuando algo falle.",
