  pros: ["Su batería LG de 36 V y 17,5 Ah va alojada en la plataforma y suma 630 Wh: es el motivo de que la estimación real se quede en 49 km, distancia que en un patinete de 350 W solo se ve en modelos pensados expresamente para trayectos largos", "El antirrobo es doble y viene de serie, sin comprar nada aparte: código de tres dígitos en la pantalla para desbloquearlo y cable de acero integrado en el mástil con combinación propia para atarlo en paradas cortas", "Si mantienes el acelerador de pulgar fijo unos 10 segundos entra el control de crucero y, con el botón de menos mantenido, tienes modo peatón a unos 5 km/h para acompañarlo andando entre gente sin empujarlo a pulso", "Las cubiertas neumáticas de 10 pulgadas con perfil redondeado son aquí toda la amortiguación que hay: permiten inclinarse en curva con más confianza que una rueda de 8,5 pulgadas y filtran juntas y adoquín ligero a cambio de vigilar pinchazos"],
  contras: ["La suma no perdona en portabilidad: 20,9 kg de patinete para una carga máxima de solo 100 kg deja poco margen a conductores corpulentos con mochila, justo al revés que rivales de su precio que admiten 120 kg pesando menos", "De fábrica llega tarado a 32 km/h y esta ficha no le verifica el certificado DGT, así que en España hay que limitarlo a 25 km/h y asumir esa incertidumbre administrativa antes de comprarlo importado", "Sin suspensión delante ni detrás, todo el trabajo recae en el aire de las ruedas de 10 pulgadas: en firme roto la plataforma, que es donde va la batería de 630 Wh, recibe los golpes de bordillos y baches sin ninguna ayuda mecánica", "Los 749 € son aproximados y no hay distribución ni servicio técnico oficial de Gotrax en España: una avería de motor o de batería LG toca gestionarla con el vendedor o con el soporte estadounidense de la marca"],
  veredicto: "El GMAX Ultra juega una sola carta y la juega fuerte: 630 Wh de batería LG para pasar de 72 km declarados a unos 49 km reales por 749 €, con un motor de 350 W nominales pensado para llanear a 25 km/h, no para cuestas duras. Encaja si vives en llano, lo dejas fijo en un garaje y recorres distancias largas sin subirlo a pulso; no encaja si pesas cerca de su límite de 100 kg, necesitas certificado DGT verificado o servicio oficial en España, o tienes que cargarlo por escaleras con sus 20,9 kg.",
